{
  "findings": [
    {
      "check_id": "CKV_GCP_120",
      "title": "Cloud SQL instance has deletion protection disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The 'deletion_protection' attribute is explicitly set to false, allowing accidental or malicious destruction of the database instance and its data."
    },
    {
      "check_id": "CKV_GCP_123",
      "title": "Cloud SQL instance does not have automated backups enabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "Automated backups are disabled ('enabled = false'), which prevents point-in-time recovery and increases the risk of permanent data loss in case of failure or corruption."
    },
    {
      "check_id": "CKV_GCP_124",
      "title": "Cloud SQL instance does not require SSL connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "SSL is not required ('require_ssl = false'), meaning database traffic may be transmitted in plaintext, exposing sensitive metadata to interception."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = true\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"off\"\n    }\n  }\n}",
  "fix_summary": "Enabled deletion protection to prevent accidental resource destruction. Enabled automated backups for disaster recovery. Enforced SSL requirements for secure database connections."
}
